  /**
   * The time that the job started, in ISO 8601 format.
   *
   * @format date-time
   */
  started_at: string;
  /**
   * The time that the job finished, in ISO 8601 format.
   *
   * @format date-time
   */
  completed_at:
    | string
    | /**
     * The time that the job finished, in ISO 8601 format.
     *
     * @format date-time
     */ null;
  /** The name of the job. */
  name: string;
  /** Steps in this job. */
