  /** The ID of the runner to which this job has been assigned. (If a runner hasn't yet been assigned, this will be null.) */
  runner_id:
    | number
    | /** The ID of the runner to which this job has been assigned. (If a runner hasn't yet been assigned, this will be null.) */ null;
  /** The name of the runner to which this job has been assigned. (If a runner hasn't yet been assigned, this will be null.) */
  runner_name:
    | string
    | /** The name of the runner to which this job has been assigned. (If a runner hasn't yet been assigned, this will be null.) */ null;
