/** An actor that can bypass rules in a ruleset */
export type RepositoryRulesetBypassActor = {
  /** The ID of the actor that can bypass a ruleset. Required for `Integration`, `RepositoryRole`, and `Team` actor types. If `actor_type` is `OrganizationAdmin`, this should be `1`. If `actor_type` is `DeployKey`, this should be null. `OrganizationAdmin` is not applicable for personal repositories. */
  actor_id?:
    | number
    | /** The ID of the actor that can bypass a ruleset. Required for `Integration`, `RepositoryRole`, and `Team` actor types. If `actor_type` is `OrganizationAdmin`, this should be `1`. If `actor_type` is `DeployKey`, this should be null. `OrganizationAdmin` is not applicable for personal repositories. */ null;
  actor_type: "Integration" | "OrganizationAdmin" | "RepositoryRole" | "Team" | "DeployKey";
  bypass_mode?: "always" | "pull_request" | "exempt";
};

/** Parameters for a repository ruleset ref name condition */
export type RepositoryRulesetConditions = {
  ref_name?: {
    /** Array of ref names or patterns to include. One of these patterns must match for the condition to pass. Also accepts `~DEFAULT_BRANCH` to include the default branch or `~ALL` to include all branches. */
    include?: string[];
    /** Array of ref names or patterns to exclude. The condition will not pass if any of these patterns match. */
    exclude?: string[];
  };
};

/** Parameters for a repository ID condition */
export type RepositoryRulesetConditionsRepositoryIdTarget = {
  repository_id: {
    /** The repository IDs that the ruleset applies to. One of these IDs must match for the condition to pass. */
    repository_ids?: number[];
  };
};

/** Parameters for a repository name condition */
export type RepositoryRulesetConditionsRepositoryNameTarget = {
  repository_name: {
    /** Array of repository names or patterns to include. One of these patterns must match for the condition to pass. Also accepts `~ALL` to include all repositories. */
    include?: string[];
    /** Array of repository names or patterns to exclude. The condition will not pass if any of these patterns match. */
    exclude?: string[];
    /** Whether renaming of target repositories is prevented. */
    protected?: boolean;
  };
};

/** Parameters for a targeting a repository property */
export type RepositoryRulesetConditionsRepositoryPropertySpec = {
  /** The name of the repository property to target */
  name: string;
  /** The values to match for the repository property */
  property_values: string[];
  source?: "custom" | "system";
};

/** Parameters for a repository property condition */
export type RepositoryRulesetConditionsRepositoryPropertyTarget = {
  repository_property: {
    /** The repository properties and values to include. All of these properties must match for the condition to pass. */
    include?: RepositoryRulesetConditionsRepositoryPropertySpec[];
    /** The repository properties and values to exclude. The condition will not pass if any of these properties match. */
    exclude?: RepositoryRulesetConditionsRepositoryPropertySpec[];
  };
};

export type OrgRulesetConditions =
  | (RepositoryRulesetConditions & RepositoryRulesetConditionsRepositoryNameTarget)
  | (RepositoryRulesetConditions & RepositoryRulesetConditionsRepositoryIdTarget)
  | (RepositoryRulesetConditions & RepositoryRulesetConditionsRepositoryPropertyTarget);

