/** Details for the GitHub Security Advisory. */
export type DependabotAlertSecurityAdvisory = {
  /** The unique GitHub Security Advisory ID assigned to the advisory. */
  ghsa_id: string;
  /** The unique CVE ID assigned to the advisory. */
  cve_id:
    | string
    | /** The unique CVE ID assigned to the advisory. */ null;
  /** A short, plain text summary of the advisory. */
  summary: string;
  /** A long-form Markdown-supported description of the advisory. */
  description: string;
  /** Vulnerable version range information for the advisory. */
  vulnerabilities: DependabotAlertSecurityVulnerability[];
  severity: "low" | "medium" | "high" | "critical";
  /** Details for the advisory pertaining to the Common Vulnerability Scoring System. */
  cvss: {
    /** The overall CVSS score of the advisory. */
    score: number;
    /** The full CVSS vector string for the advisory. */
    vector_string:
      | string
      | /** The full CVSS vector string for the advisory. */ null;
  };
  cvss_severities?: CvssSeverities;
  epss?: SecurityAdvisoryEpss;
  /** Details for the advisory pertaining to Common Weakness Enumeration. */
  cwes: /** A CWE weakness assigned to the advisory. */
    {
      /** The unique CWE ID. */
      cwe_id: string;
      /** The short, plain text name of the CWE. */
      name: string;
    }[];
  /** Values that identify this advisory among security information sources. */
  identifiers: (
    /** An advisory identifier. */
    {
      type: "CVE" | "GHSA";
      /** The value of the advisory identifer. */
      value: string;
    }
  )[];
  /** Links to additional advisory information. */
  references: /** A link to additional advisory information. */
    {
      /**
       * The URL of the reference.
       *
       * @format uri
       */
      url: string;
    }[];
  /**
   * The time that the advisory was published in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.
   *
   * @format date-time
   */
  published_at: string;
  /**
   * The time that the advisory was last modified in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.
   *
   * @format date-time
   */
  updated_at: string;
  /**
   * The time that the advisory was withdrawn in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.
   *
   * @format date-time
   */
  withdrawn_at:
    | string
    | /**
     * The time that the advisory was withdrawn in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`.
     *
     * @format date-time
     */ null;
};

