export type WebhookCodeScanningAlertReopened = {
  action: "reopened";
  /** The code scanning alert involved in the event. */
  alert:
    | {
      assignees?: SimpleUser[];
      /**
       * The time that the alert was created in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ.`
       *
       * @format date-time
       */
      created_at: string;
      /** The time that the alert was dismissed in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`. */
      dismissed_at:
        | string
        | /** The time that the alert was dismissed in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`. */ null;
      dismissed_by: Record<string, never> | null;
      dismissed_comment?: CodeScanningAlertDismissedComment;
      /** The reason for dismissing or closing the alert. Can be one of: `false positive`, `won't fix`, and `used in tests`. */
      dismissed_reason:
        | string
        | /** The reason for dismissing or closing the alert. Can be one of: `false positive`, `won't fix`, and `used in tests`. */ null;
      /** The time that the alert was fixed in ISO 8601 format: `YYYY-MM-DDTHH:MM:SSZ`. */
      fixed_at?: null;
      /**
       * The GitHub URL of the alert resource.
       *
       * @format uri
       */
      html_url: string;
      most_recent_instance?: {
        /** Identifies the configuration under which the analysis was executed. For example, in GitHub Actions this includes the workflow filename and job name. */
        analysis_key: string;
        /** Identifies the configuration under which the analysis was executed. */
        category?: string;
        classifications?: string[];
        commit_sha?: string;
        /** Identifies the variable values associated with the environment in which the analysis that generated this alert instance was performed, such as the language that was analyzed. */
        environment: string;
        location?: {
          end_column?: number;
          end_line?: number;
          path?: string;
          start_column?: number;
          start_line?: number;
        };
        message?: {
          text?: string;
        };
        /** The full Git reference, formatted as `refs/heads/<branch name>`. */
        ref: string;
        state: "open" | "dismissed" | "fixed";
      } | null;
      /** The code scanning alert number. */
      number: number;
      rule: {
        /** A short description of the rule used to detect the alert. */
        description: string;
        full_description?: string;
        help?: string | null;
        /** A link to the documentation for the rule used to detect the alert. */
        help_uri?:
          | string
          | /** A link to the documentation for the rule used to detect the alert. */ null;
        /** A unique identifier for the rule used to detect the alert. */
        id: string;
        name?: string;
        severity: "none" | "note" | "warning" | "error" | null;
        tags?: string[] | null;
      };
      state: "open" | "dismissed" | "fixed" | null;
      tool: {
        guid?: string | null;
        /** The name of the tool used to generate the code scanning analysis alert. */
        name: string;
        /** The version of the tool used to detect the alert. */
        version:
          | string
          | /** The version of the tool used to detect the alert. */ null;
      };
      /** @format uri */
      url: string;
    }
    | /** The code scanning alert involved in the event. */ null;
  /** The commit SHA of the code scanning alert. When the action is `reopened_by_user` or `closed_by_user`, the event was triggered by the `sender` and this value will be empty. */
  commit_oid:
    | string
    | /** The commit SHA of the code scanning alert. When the action is `reopened_by_user` or `closed_by_user`, the event was triggered by the `sender` and this value will be empty. */ null;
  enterprise?: EnterpriseWebhooks;
  installation?: SimpleInstallation;
  organization?: OrganizationSimpleWebhooks;
  /** The Git reference of the code scanning alert. When the action is `reopened_by_user` or `closed_by_user`, the event was triggered by the `sender` and this value will be empty. */
  ref:
    | string
    | /** The Git reference of the code scanning alert. When the action is `reopened_by_user` or `closed_by_user`, the event was triggered by the `sender` and this value will be empty. */ null;
  repository: RepositoryWebhooks;
  sender: SimpleUser;
};

