/** A GitHub Actions workflow */
export type Workflow = {
  id: number;
  node_id: string;
  name: string;
  path: string;
  state: "active" | "deleted" | "disabled_fork" | "disabled_inactivity" | "disabled_manually";
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  updated_at: string;
  url: string;
  html_url: string;
  badge_url: string;
  /** @format date-time */
  deleted_at?: string;
};

/** An invocation of a workflow */
export type WorkflowRun = {
  /** The ID of the workflow run. */
  id: number;
  /** The name of the workflow run. */
  name?:
    | string
    | /** The name of the workflow run. */ null;
  node_id: string;
  /** The ID of the associated check suite. */
  check_suite_id?: number;
  /** The node ID of the associated check suite. */
  check_suite_node_id?: string;
  head_branch: string | null;
  /** The SHA of the head commit that points to the version of the workflow being run. */
  head_sha: string;
  /** The full path of the workflow */
  path: string;
  /** The auto incrementing run number for the workflow run. */
  run_number: number;
  /** Attempt number of the run, 1 for first attempt and higher if the workflow was re-run. */
  run_attempt?: number;
  referenced_workflows?: ReferencedWorkflow[] | null;
  event: string;
  status: string | null;
  conclusion: string | null;
  /** The ID of the parent workflow. */
  workflow_id: number;
  /** The URL to the workflow run. */
  url: string;
  html_url: string;
  /** Pull requests that are open with a `head_sha` or `head_branch` that matches the workflow run. The returned pull requests do not necessarily indicate pull requests that triggered the run. */
  pull_requests:
    | PullRequestMinimal[]
    | /** Pull requests that are open with a `head_sha` or `head_branch` that matches the workflow run. The returned pull requests do not necessarily indicate pull requests that triggered the run. */ null;
  /** @format date-time */
  created_at: string;
  /** @format date-time */
  updated_at: string;
  actor?: SimpleUser;
  triggering_actor?: SimpleUser;
  /**
   * The start time of the latest run. Resets on re-run.
   *
   * @format date-time
   */
  run_started_at?: string;
  /** The URL to the jobs for the workflow run. */
  jobs_url: string;
  /** The URL to download the logs for the workflow run. */
  logs_url: string;
  /** The URL to the associated check suite. */
  check_suite_url: string;
  /** The URL to the artifacts for the workflow run. */
  artifacts_url: string;
  /** The URL to cancel the workflow run. */
  cancel_url: string;
  /** The URL to rerun the workflow run. */
  rerun_url: string;
  /** The URL to the previous attempted run of this workflow, if one exists. */
  previous_attempt_url?:
    | string
    | /** The URL to the previous attempted run of this workflow, if one exists. */ null;
  /** The URL to the workflow. */
  workflow_url: string;
  head_commit: null | SimpleCommit;
  repository: MinimalRepository;
  head_repository: MinimalRepository;
  head_repository_id?: number;
  /** The event-specific title associated with the run or the run-name if set, or the value of `run-name` if it is set in the workflow. */
  display_title: string;
};

/** Workflow Run Usage */
export type WorkflowRunUsage = {
  billable: {
    UBUNTU?: {
      total_ms: number;
      jobs: number;
      job_runs?: {
        job_id: number;
        duration_ms: number;
      }[];
    };
    MACOS?: {
      total_ms: number;
      jobs: number;
      job_runs?: {
        job_id: number;
        duration_ms: number;
      }[];
    };
    WINDOWS?: {
      total_ms: number;
      jobs: number;
      job_runs?: {
        job_id: number;
        duration_ms: number;
      }[];
    };
  };
  run_duration_ms?: number;
};

/** Workflow Usage */
export type WorkflowUsage = {
  billable: {
    UBUNTU?: {
      total_ms?: number;
    };
    MACOS?: {
      total_ms?: number;
    };
    WINDOWS?: {
      total_ms?: number;
    };
  };
};

