/**
 * List issues assigned to the authenticated user
 *
 * List issues assigned to the authenticated user across all visible repositories including owned repositories, member
 * repositories, and organization repositories. You can use the `filter` query parameter to fetch issues that are not
 * necessarily assigned to you.
 *
 * > [!NOTE]
 * > GitHub's REST API considers every pull request an issue, but not every issue is a pull request. For this reason, "Issues" endpoints may return both issues and pull requests in the response. You can identify pull requests by the `pull_request` key. Be aware that the `id` of a pull request returned from "Issues" endpoints will be an _issue id_. To find out the pull request id, use the "[List pull requests](https://docs.github.com/rest/pulls/pulls#list-pull-requests)" endpoint.
 *
 * This endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."
 *
 * - **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.
 * - **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.
 * - **`application/vnd.github.html+json`**: Returns HTML rendered from the body's markdown. Response will include `body_html`.
 * - **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.
 */
export const issuesList = (config: OpenAPIClientConfig, request?: {
  query?: {
    /** Indicates which sorts of issues to return. `assigned` means issues assigned to you. `created` means issues created by you. `mentioned` means issues mentioning you. `subscribed` means issues you're subscribed to updates for. `all` or `repos` means all issues you can see, regardless of participation or creation. */
    filter?: "assigned" | "created" | "mentioned" | "subscribed" | "repos" | "all";
    /** Indicates the state of the issues to return. */
    state?: "open" | "closed" | "all";
    /** A list of comma separated label names. Example: `bug,ui,@high` */
    labels?: string;
    /** What to sort results by. */
    sort?: "created" | "updated" | "comments";
    /** The direction to sort the results by. */
    direction?: "asc" | "desc";
    /** Only show results that were last updated after the given time. This is a timestamp in [ISO 8601](https://en.wikipedia.org/wiki/ISO_8601) format: `YYYY-MM-DDTHH:MM:SSZ`. */
    since?: string;
    collab?: boolean;
    orgs?: boolean;
    owned?: boolean;
    pulls?: boolean;
    /** The number of results per page (max 100). For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)." */
    per_page?: number;
    /** The page number of the results to fetch. For more information, see "[Using pagination in the REST API](https://docs.github.com/rest/using-the-rest-api/using-pagination-in-the-rest-api)." */
    page?: number;
  };
}): Promise<
  OpenAPIResponses<{
    /** Response */
    200: {
      body: Issue[];
      headers: {
        Link?: string;
      };
    };
    304: {
      body: unknown;
    };
    404: {
      body: unknown;
    };
    422: {
      body: unknown;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/issues",
      method: "get",
      requestSchema: z.object({
        query: z.object({
          filter: z.enum(["assigned", "created", "mentioned", "subscribed", "repos", "all"]).optional(),
          state: z.enum(["open", "closed", "all"]).optional(),
          labels: z.string().optional(),
          sort: z.enum(["created", "updated", "comments"]).optional(),
          direction: z.enum(["asc", "desc"]).optional(),
          since: z.string().optional(),
          collab: z.boolean().optional(),
          orgs: z.boolean().optional(),
          owned: z.boolean().optional(),
          pulls: z.boolean().optional(),
          per_page: z.number().int().default(30).optional(),
          page: z.number().int().default(1).optional(),
        }).optional(),
      }),
      responseSchema: {
        200: z.object({
          body: z.array(IssueSchema),
          headers: z.object({
            Link: z.string().optional(),
          }),
        }),
        304: z.object({ body: z.unknown() }),
        404: z.object({ body: z.unknown() }),
        422: z.object({ body: z.unknown() }),
      },
    },
    request,
  ) as any;

