/**
 * Create artifact metadata storage record
 *
 * Create metadata storage records for artifacts associated with an organization.
 * This endpoint will create a new artifact storage record on behalf of any artifact matching the provided digest and
 * associated with a repository owned by the organization.
 */
export const orgsCreateArtifactStorageRecord = (config: OpenAPIClientConfig, request: {
  path: {
    /** The organization name. The name is not case sensitive. */
    org: string;
  };
  body: {
    /** The name of the artifact. */
    name: string;
    /** The digest of the artifact (algorithm:hex-encoded-digest). */
    digest: string;
    /**
     * The URL where the artifact is stored.
     *
     * @format uri
     */
    artifact_url?: string;
    /**
     * The path of the artifact.
     *
     * @format uri
     */
    path?: string;
    /**
     * The base URL of the artifact registry.
     *
     * @format uri
     */
    registry_url: string;
    /** The repository name within the registry. */
    repository?: string;
    status?: "active" | "eol" | "deleted";
    /**
     * The name of the GitHub repository associated with the artifact. This should be used
     * when there are no provenance attestations available for the artifact. The repository
     * must belong to the organization specified in the path parameter.
     *
     * If a provenance attestation is available for the artifact, the API will use
     * the repository information from the attestation instead of this parameter.
     */
    github_repository?: string;
  };
}): Promise<
  OpenAPIResponses<{
    /** Artifact metadata storage record stored successfully. */
    200: {
      body: {
        total_count?: number;
        storage_records?: ({
          id?: number;
          name?: string;
          digest?: string;
          artifact_url?: string | null;
          registry_url?: string;
          repository?: string | null;
          status?: string;
          created_at?: string;
          updated_at?: string;
        })[];
      };
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/orgs/{org}/artifacts/metadata/storage-record",
      method: "post",
      requestSchema: z.object({
        path: z.object({
          org: z.string(),
        }),
        body: z.object({
          name: z.string().min(1),
          digest: z.string().regex(new RegExp("^sha256:[a-f0-9]{64}$")).min(71).max(71),
          artifact_url: z.string().regex(new RegExp("^https://")).optional(),
          path: z.string().optional(),
          registry_url: z.string().regex(new RegExp("^https://")).min(1),
          repository: z.string().optional(),
          status: z.enum(["active", "eol", "deleted"]).optional(),
          github_repository: z.string().regex(new RegExp("^[A-Za-z0-9.\-_]+$")).min(1).max(100).optional(),
        }),
      }),
      responseSchema: {
        200: z.object({
          body: z.object({
            total_count: z.number().int().optional(),
            storage_records: z.array(z.object({
              id: z.number().int().optional(),
              name: z.string().optional(),
              digest: z.string().optional(),
              artifact_url: z.union([z.string(), z.null()]).optional(),
              registry_url: z.string().optional(),
              repository: z.union([z.string(), z.null()]).optional(),
              status: z.string().optional(),
              created_at: z.string().optional(),
              updated_at: z.string().optional(),
            })).optional(),
          }),
        }),
      },
    },
    request,
  ) as any;

