/**
 * Create or update a repository secret
 *
 * Creates or updates a repository secret with an encrypted value. Encrypt your secret using
 * [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."
 *
 * OAuth app tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.
 */
export const dependabotCreateOrUpdateRepoSecret = (config: OpenAPIClientConfig, request: {
  path: {
    /** The account owner of the repository. The name is not case sensitive. */
    owner: string;
    /** The name of the repository without the `.git` extension. The name is not case sensitive. */
    repo: string;
    /** The name of the secret. */
    secret_name: string;
  };
  body: {
    /** Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get a repository public key](https://docs.github.com/rest/dependabot/secrets#get-a-repository-public-key) endpoint. */
    encrypted_value?: string;
    /** ID of the key you used to encrypt the secret. */
    key_id?: string;
  };
}): Promise<
  OpenAPIResponses<{
    /** Response when creating a secret */
    201: {
      body: EmptyObject;
    };
    /** Response when updating a secret */
    204: {
      body: unknown;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/repos/{owner}/{repo}/dependabot/secrets/{secret_name}",
      method: "put",
      requestSchema: z.object({
        path: z.object({
          owner: z.string(),
          repo: z.string(),
          secret_name: z.string(),
        }),
        body: z.object({
          encrypted_value: z.string().regex(
            new RegExp("^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{4})$"),
          ).optional(),
          key_id: z.string().optional(),
        }),
      }),
      responseSchema: {
        201: z.object({ body: EmptyObjectSchema }),
        204: z.object({ body: z.unknown() }),
      },
    },
    request,
  ) as any;

