/**
 * Create or update an environment secret
 *
 * Creates or updates an environment secret with an encrypted value. Encrypt your secret using
 * [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages). For more information, see "[Encrypting secrets for the REST API](https://docs.github.com/rest/guides/encrypting-secrets-for-the-rest-api)."
 *
 * Authenticated users must have collaborator access to a repository to create, update, or read secrets.
 *
 * OAuth tokens and personal access tokens (classic) need the `repo` scope to use this endpoint.
 */
export const actionsCreateOrUpdateEnvironmentSecret = (config: OpenAPIClientConfig, request: {
  path: {
    /** The account owner of the repository. The name is not case sensitive. */
    owner: string;
    /** The name of the repository without the `.git` extension. The name is not case sensitive. */
    repo: string;
    /** The name of the environment. The name must be URL encoded. For example, any slashes in the name must be replaced with `%2F`. */
    environment_name: string;
    /** The name of the secret. */
    secret_name: string;
  };
  body: {
    /** Value for your secret, encrypted with [LibSodium](https://libsodium.gitbook.io/doc/bindings_for_other_languages) using the public key retrieved from the [Get an environment public key](https://docs.github.com/rest/actions/secrets#get-an-environment-public-key) endpoint. */
    encrypted_value: string;
    /** ID of the key you used to encrypt the secret. */
    key_id: string;
  };
}): Promise<
  OpenAPIResponses<{
    /** Response when creating a secret */
    201: {
      body: EmptyObject;
    };
    /** Response when updating a secret */
    204: {
      body: unknown;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/repos/{owner}/{repo}/environments/{environment_name}/secrets/{secret_name}",
      method: "put",
      requestSchema: z.object({
        path: z.object({
          owner: z.string(),
          repo: z.string(),
          environment_name: z.string(),
          secret_name: z.string(),
        }),
        body: z.object({
          encrypted_value: z.string().regex(
            new RegExp("^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=|[A-Za-z0-9+/]{4})$"),
          ),
          key_id: z.string(),
        }),
      }),
      responseSchema: {
        201: z.object({ body: EmptyObjectSchema }),
        204: z.object({ body: z.unknown() }),
      },
    },
    request,
  ) as any;

