/**
 * Get an issue
 *
 * The API returns a [`301 Moved Permanently` status](https://docs.github.com/rest/guides/best-practices-for-using-the-rest-api#follow-redirects) if the issue was
 * [transferred](https://docs.github.com/articles/transferring-an-issue-to-another-repository/) to another repository. If
 * the issue was transferred to or deleted from a repository where the authenticated user lacks read access, the API
 * returns a `404 Not Found` status. If the issue was deleted from a repository where the authenticated user has read
 * access, the API returns a `410 Gone` status. To receive webhook events for transferred and deleted issues, subscribe
 * to the [`issues`](https://docs.github.com/webhooks/event-payloads/#issues) webhook.
 *
 * > [!NOTE]
 * > GitHub's REST API considers every pull request an issue, but not every issue is a pull request. For this reason, "Issues" endpoints may return both issues and pull requests in the response. You can identify pull requests by the `pull_request` key. Be aware that the `id` of a pull request returned from "Issues" endpoints will be an _issue id_. To find out the pull request id, use the "[List pull requests](https://docs.github.com/rest/pulls/pulls#list-pull-requests)" endpoint.
 *
 * This endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."
 *
 * - **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.
 * - **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.
 * - **`application/vnd.github.html+json`**: Returns HTML rendered from the body's markdown. Response will include `body_html`.
 * - **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.
 */
export const issuesGet = (config: OpenAPIClientConfig, request: {
  path: {
    /** The account owner of the repository. The name is not case sensitive. */
    owner: string;
    /** The name of the repository without the `.git` extension. The name is not case sensitive. */
    repo: string;
    /** The number that identifies the issue. */
    issue_number: number;
  };
}): Promise<
  OpenAPIResponses<{
    /** Response */
    200: {
      body: Issue;
    };
    301: {
      body: unknown;
    };
    304: {
      body: unknown;
    };
    404: {
      body: unknown;
    };
    410: {
      body: unknown;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/repos/{owner}/{repo}/issues/{issue_number}",
      method: "get",
      requestSchema: z.object({
        path: z.object({
          owner: z.string(),
          repo: z.string(),
          issue_number: z.number().int(),
        }),
      }),
      responseSchema: {
        200: z.object({ body: IssueSchema }),
        301: z.object({ body: z.unknown() }),
        304: z.object({ body: z.unknown() }),
        404: z.object({ body: z.unknown() }),
        410: z.object({ body: z.unknown() }),
      },
    },
    request,
  ) as any;

/**
 * Update an issue
 *
 * Issue owners and users with push access or Triage role can edit an issue.
 *
 * This endpoint supports the following custom media types. For more information, see "[Media types](https://docs.github.com/rest/using-the-rest-api/getting-started-with-the-rest-api#media-types)."
 *
 * - **`application/vnd.github.raw+json`**: Returns the raw markdown body. Response will include `body`. This is the default if you do not pass any specific media type.
 * - **`application/vnd.github.text+json`**: Returns a text only representation of the markdown body. Response will include `body_text`.
 * - **`application/vnd.github.html+json`**: Returns HTML rendered from the body's markdown. Response will include `body_html`.
 * - **`application/vnd.github.full+json`**: Returns raw, text, and HTML representations. Response will include `body`, `body_text`, and `body_html`.
 */
export const issuesUpdate = (config: OpenAPIClientConfig, request: {
  path: {
    /** The account owner of the repository. The name is not case sensitive. */
    owner: string;
    /** The name of the repository without the `.git` extension. The name is not case sensitive. */
    repo: string;
    /** The number that identifies the issue. */
    issue_number: number;
  };
  body?: {
    title?: string | number;
    /** The contents of the issue. */
    body?:
      | string
      | /** The contents of the issue. */ null;
    /** Username to assign to this issue. **This field is closing down.** */
    assignee?:
      | string
      | /** Username to assign to this issue. **This field is closing down.** */ null;
    state?: "open" | "closed";
    state_reason?: "completed" | "not_planned" | "duplicate" | "reopened" | null;
    milestone?:
      | string
      | /** The `number` of the milestone to associate this issue with or use `null` to remove the current milestone. Only users with push access can set the milestone for issues. Without push access to the repository, milestone changes are silently dropped. */ number;
    /** Labels to associate with this issue. Pass one or more labels to _replace_ the set of labels on this issue. Send an empty array (`[]`) to clear all labels from the issue. Only users with push access can set labels for issues. Without push access to the repository, label changes are silently dropped. */
    labels?: (
      | string
      | ({
        id?: number;
        name?: string;
        description?: string | null;
        color?: string | null;
      })
    )[];
    /** Usernames to assign to this issue. Pass one or more user logins to _replace_ the set of assignees on this issue. Send an empty array (`[]`) to clear all assignees from the issue. Only users with push access can set assignees for new issues. Without push access to the repository, assignee changes are silently dropped. */
    assignees?: string[];
    /** The name of the issue type to associate with this issue or use `null` to remove the current issue type. Only users with push access can set the type for issues. Without push access to the repository, type changes are silently dropped. */
    type?:
      | string
      | /** The name of the issue type to associate with this issue or use `null` to remove the current issue type. Only users with push access can set the type for issues. Without push access to the repository, type changes are silently dropped. */ null;
  };
}): Promise<
  OpenAPIResponses<{
    /** Response */
    200: {
      body: Issue;
    };
    301: {
      body: unknown;
    };
    403: {
      body: unknown;
    };
    404: {
      body: unknown;
    };
    410: {
      body: unknown;
    };
    422: {
      body: unknown;
    };
    503: {
      body: unknown;
    };
  }>
> =>
  openAPIFetch(
    config,
    {
      path: "/repos/{owner}/{repo}/issues/{issue_number}",
      method: "patch",
      requestSchema: z.object({
        path: z.object({
          owner: z.string(),
          repo: z.string(),
          issue_number: z.number().int(),
        }),
        body: z.object({
          title: z.union([z.string(), z.number().int()]).optional(),
          body: z.union([z.string(), z.null()]).optional(),
          assignee: z.union([z.string(), z.null()]).optional(),
          state: z.enum(["open", "closed"]).optional(),
          state_reason: z.union([
            z.literal("completed"),
            z.literal("not_planned"),
            z.literal("duplicate"),
            z.literal("reopened"),
            z.literal(null),
          ]).optional(),
          milestone: z.union([z.string(), z.number().int()]).optional(),
          labels: z.array(z.union([
            z.string(),
            z.object({
              id: z.number().int().optional(),
              name: z.string().optional(),
              description: z.union([z.string(), z.null()]).optional(),
              color: z.union([z.string(), z.null()]).optional(),
            }),
          ])).optional(),
          assignees: z.array(z.string()).optional(),
          type: z.union([z.string(), z.null()]).optional(),
        }).optional(),
      }),
      responseSchema: {
        200: z.object({ body: IssueSchema }),
        301: z.object({ body: z.unknown() }),
        403: z.object({ body: z.unknown() }),
        404: z.object({ body: z.unknown() }),
        410: z.object({ body: z.unknown() }),
        422: z.object({ body: z.unknown() }),
        503: z.object({ body: z.unknown() }),
      },
    },
    request,
  ) as any;

